import * as React from "react";
import "./TopNav.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";

export interface TopNavItemProps {

  index: number;
  openIndex: number | null ;
  navItem: {
    label?: string;
    header?: string;
    desc?: string,
    link?: string,
    menuItems: {
      label?: string;
      leadingIcon?: keyof typeof SvgMpaIcon | string;      
      showDivider?: boolean;
      disabled?: boolean;
      subMenuItems?: TopNavItemProps["navItem"]["menuItems"];
    }[];
  };
  
}


const TopNavItem: React.FC<TopNavItemProps> = ({
    index,
    openIndex,
    navItem,
}) => {

    return (
      <>
        <span className="name">{navItem.label}</span>
        {navItem.menuItems && (
            <span className="sub-menu-arrow">
              <span  className={`toggle-btn ${openIndex === index ? 'rotate' : ''}`}>
                <MpaIcon iconName={'ChevronDown'}/>
              </span>
            {/* <FontAwesomeIcon
                icon={faChevronDown}
                className={`toggle-btn ${openIndex === index ? 'rotate' : ''}`}
            /> */}
            </span>
        )}
      </>
    );
};

export default TopNavItem;
